const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Central Valley of California geometry (approximate bounds)
  const centralValley = ee.Geometry.Polygon([
    [[-122.5, 35.0], [-122.5, 40.5], [-119.0, 40.5], [-119.0, 35.0], [-122.5, 35.0]]
  ]);

  // 2. Define time periods
  const oct2022Start = '2022-10-01';
  const oct2022End = '2022-10-31';
  const march2023Start = '2023-03-01';
  const march2023End = '2023-03-31';

  // 3. Load GRACE-FO data (Liquid Water Equivalent thickness)
  const graceCollection = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
    .select(['SWE_inst']); // Snow Water Equivalent + soil moisture

  // Try GRACE for better water storage
  const graceWater = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/MASCON_CRI')
    .select(['lwe_thickness']);

  // Get October 2022 data
  const oct2022 = graceWater
    .filterDate(oct2022Start, oct2022End)
    .filterBounds(centralValley);

  const oct2022Size = oct2022.size().getInfo();
  console.log('Oct 2022 images:', oct2022Size);

  if (oct2022Size === 0) {
    console.log('No data for October 2022');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get March 2023 data
  const march2023 = graceWater
    .filterDate(march2023Start, march2023End)
    .filterBounds(centralValley);

  const march2023Size = march2023.size().getInfo();
  console.log('March 2023 images:', march2023Size);

  if (march2023Size === 0) {
    console.log('No data for March 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate mean water equivalent for each period
  const oct2022Mean = oct2022.mean();
  const march2023Mean = march2023.mean();

  // Reduce to get average over Central Valley
  const oct2022Stats = oct2022Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 10000,
    maxPixels: 1e9
  });

  const march2023Stats = march2023Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 10000,
    maxPixels: 1e9
  });

  const oct2022Value = oct2022Stats.get('lwe_thickness').getInfo();
  const march2023Value = march2023Stats.get('lwe_thickness').getInfo();

  console.log('Oct 2022 water equivalent (cm):', oct2022Value);
  console.log('March 2023 water equivalent (cm):', march2023Value);

  // 5. Validation and answer
  if (oct2022Value === null || march2023Value === null || 
      isNaN(oct2022Value) || isNaN(march2023Value)) {
    console.log('Calculation failed - invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare values
  if (oct2022Value > march2023Value) {
    console.log('October 2022 had higher water height equivalent');
    console.log('<answer>A</answer>');
  } else {
    console.log('October 2022 did NOT have higher water height equivalent');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
